    public static SVGPath createIcon(String name, String fillHex, double scale) {
        String pathData = SVG_PATHS.getOrDefault(name.toUpperCase(), SVG_PATHS.get("OTHERS"));
        SVGPath svg = new SVGPath();
        svg.setContent(pathData);
        svg.setFill(Color.web(fillHex));
        svg.setScaleX(scale);
        svg.setScaleY(scale);
        return svg;
    }

    public static Node createCategoryBadge(String iconName, String colorHex, double size) {
        StackPane badge = new StackPane();
        badge.setAlignment(Pos.CENTER);
        badge.setPrefSize(size, size);
        badge.setMinSize(size, size);
        badge.setMaxSize(size, size);

        Circle circle = new Circle(size / 2.0);
        Color baseColor = Color.web(colorHex != null ? colorHex : "#78BFA0");
        // Soft pastel background
        circle.setFill(Color.color(baseColor.getRed(), baseColor.getGreen(), baseColor.getBlue(), 0.22));

        double iconScale = (size / 24.0) * 0.6;
        SVGPath icon = createIcon(iconName, colorHex != null ? colorHex : "#78BFA0", iconScale);

        badge.getChildren().addAll(circle, icon);
        return badge;
    }
